public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    /**
     * Searches for records based on the provided object, fields, and filters.
     * 
     * @param objectApiName The API name of the object to search.
     * @param fields A list of field API names to include in the SELECT clause.
     * @param filters A map of field API names and their equality filter values.
     * @param orderByField The field API name to sort by (ascending).
     * @param maxRows The maximum number of rows to return (1-200).
     * @return A list of SObjects matching the criteria.
     * @throws SearchException if any validation fails or security restrictions are met.
     */
    public static List<SObject> search(
        String objectApiName, 
        List<String> fields, 
        Map<String, Object> filters, 
        String orderByField, 
        Integer maxRows
    ) {
        try {
            // 1. Validate maxRows
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            // 2. Validate Object existence and accessibility
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name is required.');
            }

            SObjectType sObjectType = Schema.getGlobalDescribe().get(objectApiName);
            if (sObjectType == null) {
                throw new SearchException('Object ' + objectApiName + ' does not exist.');
            }

            DescribeSObjectResult objDescribe = sObjectType.getDescribe();
            if (!objDescribe.isAccessible()) {
                throw new SearchException('The running user does not have access to the object: ' + objectApiName);
            }

            // 3. Validate fields list
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('The fields list cannot be null or empty.');
            }

            // 4. Prepare field map for case-insensitive lookups and validation
            Map<String, SObjectField> fieldMap = objDescribe.fields.getMap();
            Map<String, SObjectField> caseInsensitiveFieldMap = new Map<String, SObjectField>();
            for (String fKey : fieldMap.keySet()) {
                caseInsensitiveFieldMap.put(fKey.toLowerCase(), fieldMap.get(fKey));
            }

            // 5. Validate SELECT fields
            for (String f : fields) {
                String lowerF = f.toLowerCase();
                if (!caseInsensitiveFieldMap.containsKey(lowerF)) {
                    throw new SearchException('Field ' + f + ' does not exist on ' + objectApiName);
                }
                if (!caseInsensitiveFieldMap.get(lowerF).getDescribe().isAccessible()) {
                    throw new SearchException('The running user does not have access to field: ' + f);
                }
            }

            // 6. Validate Filters and build WHERE clause
            Map<String, Object> bindParams = new Map<String, Object>();
            List<String> whereClauses = new List<String>();
            if (filters != null && !filters.isEmpty()) {
                Integer idx = 0;
                for (String f : filters.keySet()) {
                    String lowerF = f.toLowerCase();
                    if (!caseInsensitiveFieldMap.containsKey(lowerF)) {
                        throw new SearchException('Filter field ' + f + ' does not exist on ' + objectApiName);
                    }

                    SObjectField sf = caseInsensitiveFieldMap.get(lowerF);
                    DescribeSObjectField fd = sf.getDescribe();

                    if (!fd.isAccessible()) {
                        throw new SearchException('The running user does not have access to filter field: ' + f);
                    }
                    if (!fd.isFilterable()) {
                        throw new SearchException('Filter field ' + f + ' cannot be filtered.');
                    }

                    // Create unique bind variable name to prevent collision and injection
                    String bindVarName = 'val_' + idx;
                    whereClauses.add(f + ' = :' + bindVarName);
                    bindParams.put(bindVarName, filters.get(f));
                    idx++;
                }
            }

            // 7. Validate Order-By
            if (String.isNotBlank(orderByField)) {
                String lowerOrderBy = orderByField.toLowerCase();
                if (!caseInsensitiveFieldMap.containsKey(lowerOrderBy)) {
                    throw new SearchException('Order-by field ' + orderByField + ' does not exist on ' + objectApiName);
                }

                SObjectField sf = caseInsensitiveFieldMap.get(lowerOrderBy);
                DescribeSObjectField fd = sf.getDescribe();

                if (!fd.isAccessible()) {
                    throw new SearchException('The running user does not have access to order-by field: ' + orderByField);
                }
                if (!fd.isSortable()) {
                    throw new SearchException('Order-by field ' + orderByField + ' cannot be sorted.');
                }
            }

            // 8. Build Dynamic SOQL Query
            // Use the actual API names from fieldMap to ensure exactness
            String query = 'SELECT Id';
            for (String f : fields) {
                String actualName = caseInsensitiveFieldMap.get(f.toLowerCase()).getDescribe().getName();
                query += ', ' + actualName;
            }
            query += ' FROM ' + objectApiName;

            if (!whereClauses.isEmpty()) {
                query += ' WHERE ' + String.join(whereClauses, ' AND ');
            }

            if (String.isNotBlank(orderByField)) {
                query += ' ORDER BY ' + orderByField + ' ASC';
            }

            query += ' LIMIT ' + maxRows;

            // 9. Execute query using User Mode to enforce FLS, CRUD, and Sharing
            return Database.queryWithBind(query, bindParams, AccessLevel.USER_MODE);

        } catch (SearchException e) {
            // Re-throw our specific exception type
            throw e;
        } catch (Exception e) {
            // Wrap any other unexpected exceptions in SearchException
            throw new SearchException(e.getMessage());
        }
    }
}
