public with sharing class ContactLookupAction {

    /**
     * Invocable method to find an existing contact by email.
     * Handles bulk requests, case-insensitivity, and returns the earliest contact if duplicates exist.
     */
    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        Set<String> emailsToSearch = new Set<String>();

        // 1. Collect all non-blank trimmed emails from the requests
        for (Request req : requests) {
            if (String.isNotBlank(req.email)) {
                emailsToSearch.add(req.email.trim());
            }
        }

        // 2. Map to store the earliest contact found for each unique email
        // We use lowercase email as the key to ensure case-insensitive matching in the map
        Map<String, Contact> emailToEarliestContact = new Map<String, Contact>();

        // 3. Execute a single SOQL query to find all matching contacts
        if (!emailsToSearch.isEmpty()) {
            // We order by CreatedDate ASC so that for any given email, the first contact 
            // encountered in the loop is the earliest one.
            for (Contact con : [
                SELECT Email, Id, CreatedDate 
                FROM Contact 
                WHERE Email IN :emailsToSearch 
                ORDER BY CreatedDate ASC
            ]) {
                if (con.Email != null) {
                    String emailKey = con.Email.trim().toLowerCase();
                    // Because of ORDER BY CreatedDate ASC, the first contact we encounter for 
                    // a specific email is the earliest.
                    if (!emailToEarliestContact.containsKey(emailKey)) {
                        emailToEarliestContact.put(emailKey, con);
                    }
                }
            }
        }

        // 4. Build results in the exact same order as the input requests
        for (Request req : requests) {
            Result res = new Result();
            // Prepare the input email for a case-insensitive map lookup
            String targetEmail = (req.email != null) ? req.email.trim().toLowerCase() : null;

            if (String.isNotBlank(targetEmail) && emailToEarliestContact.containsKey(targetEmail)) {
                Contact matchedContact = emailToEarliestContact.get(targetEmail);
                res.contactId = matchedContact.Id;
                res.found = true;
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;
        @InvocableVariable
        public Boolean found;
    }
}
