public with sharing class LeadImportService {

    /**
     * Result wrapper containing the summary of the import operation.
     */
    public class ImportResult {
        public Integer successCount = 0;
        public List<Id> insertedIds = new List<Id>();
        public Map<Integer, String> errorsByIndex = new Map<Integer, String>();
    }

    /**
     * Imports a list of Leads, performing validation for duplicate emails within the call
     * and setting default LeadSource.
     * 
     * @param leads The list of Lead records to attempt to insert.
     * @return An ImportResult object containing success counts, inserted IDs, and error messages.
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> originalIndices = new List<Integer>();
        Set<String> seenEmails = new Set<String>();

        // Step 1: Pre-process leads and identify local duplicates
        for (Integer i = 0; i < leads.size(); i++) {
            Lead currentLead = leads[i];

            // Set default LeadSource if blank
            if (String.isBlank(currentLead.LeadSource)) {
                currentLead.LeadSource = 'Web';
            }

            // Handle Email normalization for duplicate detection
            String normalizedEmail = (currentLead.Email != null) 
                ? currentLead.Email.trim().toLowerCase() 
                : null;

            // Check for duplicates within this specific import batch
            if (String.isNotBlank(normalizedEmail) && seenEmails.contains(normalizedEmail)) {
                result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
            } else {
                // If it's not a duplicate, prepare for DML
                if (String.isNotBlank(normalizedEmail)) {
                    seenEmails.add(normalizedEmail);
                }
                leadsToInsert.add(currentLead);
                originalIndices.add(i);
            }
        }

        // Step 2: Perform single DML operation for all non-duplicate leads
        if (!leadsToInsert.isEmpty()) {
            Database.SaveResult[] results = Database.insert(leadsToInsert, false);

            for (Integer j = 0; j < results.size(); j++) {
                Database.SaveResult sr = results[j];
                // Map the SaveResult back to its original index in the input list
                Integer originalIdx = originalIndices[j];

                if (sr.isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(sr.getId());
                } else {
                    // Aggregate all database error messages for this specific record
                    String errorMsg = '';
                    for (Database.Error err : sr.getErrors()) {
                        if (errorMsg != '') {
                            errorMsg += '; ';
                        }
                        errorMsg += err.getMessage();
                    }
                    result.errorsByIndex.put(originalIdx, errorMsg);
                }
            }
        }

        return result;
    }
}
