public class PicklistService {

    /**
     * Represents a single picklist option.
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Custom exception for PicklistService errors.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of any picklist or multi-select picklist field, 
     * in the order they are defined on the field.
     *
     * @param objectApiName The API name of the object (case-insensitive).
     * @param fieldApiName The API name of the field (case-insensitive).
     * @return A list of Option objects containing the API value, label, and default status.
     * @throws PicklistServiceException if names are null/blank, object/field doesn't exist, 
     *         or if the field is not a picklist or multi-select picklist.
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        // 1. Validate null or blank input
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field API names must be provided and cannot be blank.');
        }

        // 2. Resolve SObjectType (Case-Insensitive)
        Schema.SObjectType sObjectType = null;
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                sObjectType = globalDescribe.get(key);
                break;
            }
        }

        if (sObjectType == null) {
            throw new PicklistServiceException('The object "' + objectApiName + '" does not exist.');
        }

        // 3. Resolve Field (Case-Insensitive)
        Schema.SObjectField field = null;
        Map<String, Schema.SObjectField> fieldMap = sObjectType.getDescribe().fields.getMap();
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                field = fieldMap.get(key);
                break;
            }
        }

        if (field == null) {
            throw new PicklistServiceException('The field "' + fieldApiName + '" does not exist on the object "' + objectApiName + '".');
        }

        // 4. Validate Field Type
        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('The field "' + fieldApiName + '" is not a picklist or multi-select picklist.');
        }

        // 5. Extract Active Values
        List<Option> options = new List<Option>();
        // getPicklistValues() returns values in the order they are defined on the field.
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefault()
                ));
            }
        }

        return options;
    }
}
