public with sharing class OpportunityPipelineHandler {

    /**
     * Handles the after insert trigger context.
     */
    public static void onAfterInsert(List<Opportunity> newOpps) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity o : newOpps) {
            if (o.AccountId != null) {
                accountIds.add(o.AccountId);
            }
        }
        handleRollup(accountIds);
    }

    /**
     * Handles the after update trigger context.
     * Recalculates the Account if the AccountId changes, or if the Opportunity
     * status (IsClosed) or value (Amount) changes for an open opportunity.
     */
    public static void onAfterUpdate(List<Opportunity> newOpps, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity newO : newOpps) {
            Opportunity oldO = oldMap.get(newO.Id);

            if (newO.AccountId != oldO.AccountId) {
                // Account moved: both old and new accounts must be recalculated.
                if (newO.AccountId != null) {
                    accountIds.add(newO.AccountId);
                }
                if (oldO.AccountId != null) {
                    accountIds.add(oldO.AccountId);
                }
            } else {
                // Same account: Recalculate if it's an open opportunity or was an open opportunity.
                // This handles changes to Amount and StageName (which affects IsClosed).
                if (newO.IsClosed == false || oldO.IsClosed == false) {
                    if (newO.AccountId != null) {
                        accountIds.add(newO.AccountId);
                    }
                }
            }
        }
        handleRollup(accountIds);
    }

    /**
     * Handles the after delete trigger context.
     */
    public static void onAfterDelete(Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity oldO : oldMap.values()) {
            if (oldO.AccountId != null) {
                accountIds.add(oldO.AccountId);
            }
        }
        handleRollup(accountIds);
    }

    /**
     * Handles the after undelete trigger context.
     */
    public static void onAfterUndelete(List<Opportunity> newOpps) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity o : newOpps) {
            if (o.AccountId != null) {
                accountIds.add(o.AccountId);
            }
        }
        handleRollup(accountIds);
    }

    /**
     * The core logic that performs the aggregation and updates the Accounts.
     * Ensures accounts with no open opportunities are reset to 0 and 0.
     */
    private static void handleRollup(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // 1. Prepare a list of Account skeleton records to ensure we update
        // all affected accounts, even those that no longer have open opportunities.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accId,
                FB_Open_Pipeline__c = 0,
                FB_Open_Opportunities__c = 0
            ));
        }

        // 2. Aggregate current open opportunity data for the affected accounts.
        Map<Id, Decimal> pipelineMap = new Map<Id, Decimal>();
        Map<Id, Integer> countMap = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) totalCount
            FROM Opportunity
            WHERE IsClosed = false 
            AND AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            Id accId = (Id)ar.get('AccountId');
            Decimal sumAmount = (Decimal)ar.get('totalAmount');
            Integer count = (Integer)ar.get('totalCount');

            // Blank amounts count as 0. If SUM returns null, we set it to 0.
            pipelineMap.put(accId, sumAmount == null ? 0 : sumAmount);
            countMap.put(accId, count);
        }

        // 3. Map the aggregated results back to our skeleton account records.
        for (Account acc : accountsToUpdate) {
            if (pipelineMap.containsKey(acc.Id)) {
                acc.FB_Open_Pipeline__c = pipelineMap.get(acc.Id);
            }
            if (countMap.containsKey(acc.Id)) {
                acc.FB_Open_Opportunities__c = countMap.get(acc.Id);
            }
            // If not present in maps, the initial 0 values remain.
        }

        // 4. Perform the DML.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
