    }

    /**
     * @description Returns the open opportunities for the given account IDs, 
     * ordered by Amount (descending, nulls last) and CloseDate (ascending).
     * @param accountIds Set of Account IDs to filter by.
     * @param maxRecords Maximum number of records to return.
     * @return List of Opportunity records.
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory queryFactory = newQueryFactory();

        // Add the parent account's Name to the selector's field list
        queryFactory.addFields(new List<Schema.SObjectField>{ Account.Name });

        // Filter for open opportunities of the provided accounts
        queryFactory.setWhereClause('IsClosed = false AND AccountId IN :accountIds');

        // Order by Amount DESC (highest first), with NULL amounts last.
        // Then by CloseDate ASC (earliest first) for equal amounts.
        queryFactory.setOrderBy('Amount DESC NULLS LAST, CloseDate ASC');

        // Apply the record limit
        queryFactory.setLimit(maxRecords);

        // Execute the query using the selector's protected selectSObjects method 
        // to ensure field security/stripping is applied according to fflib best practices.
        return (List<Opportunity>) selectSObjects(queryFactory.toSOQL());
    }
}
