        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        // Dynamically add fields from the Credit_Review field set.
        // This allows admins to add fields without requiring code changes.
        Schema.FieldSet creditReviewFieldSet = Account.Credit_Review;
        for (Schema.FieldSetMember fsm : creditReviewFieldSet.getFields()) {
            fields.add(fsm.getField());
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        // Build the subquery using the ContactsSelector to ensure consistency in selected fields.
        ContactsSelector contactsSelector = new ContactsSelector();
        List<Schema.SObjectField> contactFields = contactsSelector.getSObjectFieldList();

        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : contactFields) {
            fieldNames.add(field.getDescribe().getName());
        }

        String subquery = '(SELECT ' + String.join(fieldNames, ', ') + ' FROM Contacts)';

        return (List<Account>) selectSObjectsById(accountIds, subquery);
    }
