import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    error = '';

    debounceTimer;
    lastRequestId = 0;
    isMounted = true;

    handleChange(event) {
        const value = event.target.value.trim();

        // Clear any pending debounce timer
        window.clearTimeout(this.debounceTimer);

        // If the trimmed value has fewer than 2 characters, cancel any pending search,
        // do not call Apex, and clear the results.
        if (value.length < 2) {
            this.searchTerm = value;
            this.contacts = [];
            this.error = '';
            return;
        }

        this.searchTerm = value;

        // Debounce: call searchContacts only once the user has stopped typing for 300 ms
        this.debounceTimer = setTimeout(() => {
            this.performSearch(value);
        }, 300);
    }

    async performSearch(term) {
        // If the component is unmounted, do not run the search
        if (!this.isMounted) {
            return;
        }

        // Track request sequence to handle out-of-order responses
        const requestId = ++this.lastRequestId;

        try {
            const result = await searchContacts({ searchTerm: term });

            // Only update results if this is the most recent request and the component is still mounted
            if (this.isMounted && requestId === this.lastRequestId) {
                this.contacts = result;
                this.error = '';
            }
        } catch (err) {
            // Only update error if this is the most recent request and the component is still mounted
            if (this.isMounted && requestId === this.lastRequestId) {
                this.error = err.body ? err.body.message : err.message;
                this.contacts = [];
            }
        }
    }

    disconnectedCallback() {
        this.isMounted = false;
        window.clearTimeout(this.debounceTimer);
    }
}
