public class GauAllocationService {
    public class AllocationException extends Exception {}

    /**
     * Allocates a gift across multiple General Accounting Units (GAUs) based on provided percentages.
     * Replaces all existing allocations for the given opportunity.
     * 
     * @param opportunityId The Id of the Opportunity being split.
     * @param percentByGauId A map where keys are GAU IDs and values are percentages (e.g., 60 for 60%).
     * @return List of newly inserted npsp__Allocation__c records.
     * @throws AllocationException if validation rules are violated.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // 1. Validate Map is not null or empty
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('The percentage map cannot be null or empty.');
        }

        // 2. Validate individual percentages and calculate sum
        Decimal totalPercent = 0;
        for (Decimal pct : percentByGauId.values()) {
            if (pct == null || pct <= 0) {
                throw new AllocationException('All percentages must be greater than 0.');
            }
            totalPercent += pct;
        }

        // 3. Validate total sum does not exceed 100%
        if (totalPercent > 100) {
            throw new AllocationException('The sum of percentages cannot exceed 100%.');
        }

        // 4. Validate GAUs are active and exist
        // We query only the GAUs provided in the map to minimize the query scope.
        List<npsp__General_Accounting_Unit__c> gauList = [
            SELECT Id, npsp__Active__c 
            FROM npsp__General_Accounting_Unit__c 
            WHERE Id IN :percentByGauId.keySet()
        ];

        Set<Id> activeGauIds = new Set<Id>();
        for (npsp__General_Accounting_Unit__c gau : gauList) {
            if (gau.npsp__Active__c) {
                activeGauIds.add(gau.Id);
            }
        }

        // Ensure every ID in the map is present in the activeGauIds set.
        // This covers both the "inactive" and "non-existent" scenarios.
        for (Id gauId : percentByGauId.keySet()) {
            if (!activeGauIds.contains(gauId)) {
                throw new AllocationException('One or more General Accounting Units are inactive or do not exist.');
            }
        }

        // 5. Retrieve Opportunity data
        // We need the current Amount to calculate the initial proportional amounts.
        Opportunity opp = [SELECT Amount FROM Opportunity WHERE Id = :opportunityId LIMIT 1];
        Decimal oppAmount = (opp.Amount != null) ? opp.Amount : 0;

        // 6. Replace existing allocations
        // Before creating new ones, we delete all current allocations for this Opportunity.
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id 
            FROM npsp__Allocation__c 
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // 7. Create new allocations
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);

            npsp__Allocation__c newAlloc = new npsp__Allocation__c();
            newAlloc.npsp__Opportunity__c = opportunityId;
            newAlloc.npsp__General_Accounting_Unit__c = gauId;
            newAlloc.npsp__Percent__c = pct;
            // We set the initial Amount based on the current Opportunity Amount.
            // NPSP handles future updates to the Amount automatically because npsp__Percent__c is set.
            newAlloc.npsp__Amount__c = (oppAmount * pct / 100);

            newAllocations.add(newAlloc);
        }

        // 8. Insert and return the new allocations
        insert newAllocations;
        return newAllocations;
    }
}
