public class HouseholdService {
    /**
     * Creates a new NPSP household account and associates the provided contacts with it.
     * The first contact in the list is designated as the primary contact.
     *
     * @param members A list of new Contact records to be added to the household.
     * @return The Id of the newly created Household Account.
     * @throws IllegalArgumentException if the members list is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('The members list cannot be null or empty.');
        }

        // 1. Get the HH_Account Record Type ID
        // We use DeveloperName as requested to avoid hard-coding IDs.
        Id householdRecordTypeId = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
            .get('HH_Account')
            .getRecordTypeId();

        // 2. Create the Account
        // Per requirements, we do not set the account name manually; 
        // NPSP automation will handle naming and greetings based on the primary contact.
        Account householdAccount = new Account(
            RecordTypeId = householdRecordTypeId
        );
        insert householdAccount;

        // 3. Associate all contacts with the new Account
        for (Contact member : members) {
            member.AccountId = householdAccount.Id;
        }

        // Insert the new contacts
        insert members;

        // 4. Set the first contact in the list as the primary contact
        // NPSP uses the npe01__One2OneContact__c field on the Account to identify the primary contact.
        // Updating this field will trigger NPSP's naming automation.
        householdAccount.npe01__One2OneContact__c = members[0].Id;
        update householdAccount;

        return householdAccount.Id;
    }
}
