public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Adds or updates NPSP partial soft credits and ensures the contact has the correct OpportunityContactRole.
     * 
     * @param requests A list of SoftCreditRequest objects containing opportunity, contact, amount, and role.
     * @throws SoftCreditException if validation fails (amount invalid, contact is primary contact, etc).
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) oppIds.add(req.opportunityId);
            if (req.contactId != null) contactIds.add(req.contactId);
        }

        // Query 1: Fetch Opportunities to validate against amount and primary contact
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c 
            FROM Opportunity 
            WHERE Id IN :oppIds
        ]);

        // Validation Step: Validate the entire batch before any DML
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);

            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be positive and not null.');
            }

            if (opp == null) {
                throw new SoftCreditException('The specified Opportunity does not exist.');
            }

            if (req.amount > opp.Amount) {
                throw new SoftCreditException('Soft credit amount cannot be greater than the Opportunity amount.');
            }

            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('The contact cannot be the Opportunity\'s primary contact.');
            }
        }

        // Query 2: Fetch existing OpportunityContactRoles for the provided pairs
        // We use a map with a composite key (OppId|ContactId) to manage the one-role-per-contact requirement
        Map<String, OpportunityContactRole> ocrMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role 
            FROM OpportunityContactRole 
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            String key = (String)ocr.OpportunityId + '|' + (String)ocr.ContactId;
            // If multiple roles exist, we take the first one to update, 
            // ensuring the "exactly one" requirement via transformation.
            if (!ocrMap.containsKey(key)) {
                ocrMap.put(key, ocr);
            }
        }

        // Query 3: Fetch existing Partial Soft Credits
        Map<String, npsp__Partial_Soft_Credit__c> scMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c sc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c 
            FROM npsp__Partial_Soft_Credit__c 
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            String key = (String)sc.npsp__Opportunity__c + '|' + (String)sc.npsp__Contact__c;
            if (!scMap.containsKey(key)) {
                scMap.put(key, sc);
            }
        }

        // Prepare OpportunityContactRoles for upsert
        List<OpportunityContactRole> ocrToUpsert = new List<OpportunityContactRole>();
        // Map to track newly created OCRs so we can reference their IDs later
        Map<String, OpportunityContactRole> newOCRMap = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = (String)req.opportunityId + '|' + (String)req.contactId;
            OpportunityContactRole ocr;

            if (ocrMap.containsKey(key)) {
                ocr = ocrMap.get(key);
                ocr.Role = req.role;
                ocrToUpsert.add(ocr);
            } else {
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                newOCRMap.put(key, ocr);
                ocrToUpsert.add(ocr);
            }
        }

        // Perform first DML: Upsert OpportunityContactRoles
        if (!ocrToUpsert.isEmpty()) {
            upsert ocrToUpsert;
        }

        // Prepare Partial Soft Credits for upsert
        List<npsp__Partial_Soft_Credit__c> scToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest req : requests) {
            String key = (String)req.opportunityId + '|' + (String)req.contactId;
            npsp__Partial_Soft_Credit__c sc;

            // Retrieve the correct OCR record (either existing or the one we just inserted)
            OpportunityContactRole targetOCR;
            if (ocrMap.containsKey(key)) {
                targetOCR = ocrMap.get(key);
            } else {
                targetOCR = newOCRMap.get(key);
            }

            if (scMap.containsKey(key)) {
                sc = scMap.get(key);
                sc.npsp__Amount__c = req.amount;
                sc.npsp__Role_Name__c = req.role;
                sc.npsp__Contact_Role_ID__c = (String)targetOCR.Id;
                scToUpsert.add(sc);
            } else {
                sc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = (String)targetOCR.Id
                );
                scToUpsert.add(sc);
            }
        }

        // Perform second DML: Upsert Partial Soft Credits
        if (!scToUpsert.isEmpty()) {
            upsert scToUpsert;
        }
    }
}
