```apex
public class AccountOwnershipService {
    /**
     * Reassigns the owner of the given accounts and all their related contacts.
     * 
     * @param accountIds The set of Account IDs to reassign.
     * @param newOwnerId The ID of the new owner.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Bypass all Account trigger actions to prevent expensive recalculations (e.g., territories).
        // This uses the TAF transaction bypass for the entire Account sObject.
        TriggerBase.bypass(Account.SObjectType);

        try {
            // We use a list of SObjects to perform a single mixed DML statement.
            // This ensures all-or-none DML for both Accounts and Contacts and keeps DML count low.
            List<SObject> recordsToUpdate = new List<SObject>();

            // Prepare Account updates.
            for (Id accId : accountIds) {
                recordsToUpdate.add(new Account(
                    Id = accId,
                    OwnerId = newOwnerId
                ));
            }

            // Prepare Contact updates.
            // Contacts are queried to retrieve their IDs. 
            // TAF is NOT bypassed for Contacts, so Contact trigger actions will run normally.
            for (Contact con : [SELECT Id FROM Contact WHERE AccountId IN :accountIds]) {
                con.OwnerId = newOwnerId;
                recordsToUpdate.add(con);
            }

            // Perform the single DML operation. 
            // If any record fails, the entire transaction is rolled back (all-or-none).
            if (!recordsToUpdate.isEmpty()) {
                update recordsToUpdate;
            }
        } finally {
            // Ensure that the Account bypass is cleared regardless of whether the update 
            // succeeded or an exception was thrown, allowing subsequent automation 
            // in the same transaction to run normally.
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
