public class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    /**
     * @description Normalizes Lead contact information by trimming whitespace from Email and Company,
     * lower-casing the Email, and ensuring a default LeadSource is set.
     * 
     * @param triggerNew The list of Leads being inserted.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        for (SObject so : triggerNew) {
            Lead l = (Lead)so;

            // Email: leading/trailing whitespace removed and lower-cased (a null email stays null).
            if (l.Email != null) {
                l.Email = l.Email.trim().toLowerCase();
            }

            // Company: leading/trailing whitespace removed.
            if (l.Company != null) {
                l.Company = l.Company.trim();
            }

            // LeadSource: set to Web when blank; an existing value is kept.
            if (String.isBlank(l.LeadSource)) {
                l.LeadSource = 'Web';
            }
        }
    }
}
