public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasksToInsert = new List<Task>();
        Map<Id, Opportunity> oldOppMap = new Map<Id, Opportunity>();

        for (Opportunity oldOpp : triggerOld) {
            oldOppMap.put(oldOpp.Id, oldOpp);
        }

        for (Opportunity newOpp : triggerNew) {
            Opportunity oldOpp = oldOppMap.get(newOpp.Id);
            if (oldOpp == null) {
                continue;
            }

            // Check if the Amount field has changed. 
            // Apex handles null comparisons correctly (null != 100 is true, null != null is false).
            Boolean amountChanged = (newOpp.Amount != oldOpp.Amount);

            // The Trigger Actions Framework tracks how many times an ID has been seen in the current context.
            // Because TA_Opportunity_RoundAmount (order 20) re-triggers the update, this action 
            // will be called a second time for the same records. We check if this is the first 
            // execution (timesSeen == 1) to ensure at most one task is created per transaction.
            Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(newOpp.Id);
            Boolean isFirstRun = (timesSeen == 1);

            if (amountChanged && isFirstRun) {
                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = newOpp.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
