public class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accounts = TA_Contact_Queries.getInstance().accountsById;
        if (accounts == null) {
            return;
        }

        for (SObject so : triggerNew) {
            Contact con = (Contact)so;
            if (con.AccountId != null && accounts.containsKey(con.AccountId)) {
                Account acc = accounts.get(con.AccountId);
                if (String.isBlank(con.MailingStreet) &&
                    String.isBlank(con.MailingCity) &&
                    String.isBlank(con.MailingPostalCode) &&
                    String.isBlank(con.MailingCountry)) {

                    con.MailingStreet = acc.BillingStreet;
                    con.MailingCity = acc.BillingCity;
                    con.MailingPostalCode = acc.BillingPostalCode;
                    con.MailingCountry = acc.BillingCountry;
                }
            }
        }
    }
}
